const TARANTULA_INFO={id:"gooty-sapphire-tarantula",commonName:"Gooty Sapphire Ornamental Tarantula",scientificName:"Poecilotheria metallica",family:"Theraphosidae",genus:"Poecilotheria",species:"P. metallica",endemicRegion:"Eastern Ghats Reserve Forests near Gooty & Nandyal (Andhra Pradesh)",iucnStatus:"Critically Endangered (IUCN 3.1)",protectionStatus:"Schedule IV (Indian Wildlife Protection Act, 1972)",habitatType:"Arboreal tree hollows in dry and moist deciduous reserve forests",avgSize:"15 to 20 cm diagonal leg span (Females larger than males)",lifespan:"12 to 15 years (Females) / 3 to 4 years (Males)",dietType:"Insectivorous & Small Vertebrates (Crickets, grasshoppers, moths, geckos)",quickStats:[{label:"Endemic Range",value:"Andhra Pradesh (<100 km²)",icon:"📍"},{label:"IUCN Red List",value:"Critically Endangered",icon:"🚨"},{label:"Coloration",value:"Electric Sapphire Blue",icon:"💎"},{label:"Lifestyle",value:"Arboreal Tree-Dweller",icon:"🌳"},{label:"Leg Span",value:"15–20 cm",icon:"🕷️"},{label:"Primary Threat",value:"Pet Trade & Deforestation",icon:"⚠️"}]},TAXONOMY_DATA={kingdom:"Animalia",phylum:"Arthropoda",class:"Arachnida",order:"Araneae",suborder:"Mygalomorphae",family:"Theraphosidae",genus:"Poecilotheria",species:"Poecilotheria metallica (Pocock, 1899)"},ECOLOGY_BEHAVIOUR={introduction:"The Gooty Sapphire Ornamental Tarantula (Poecilotheria metallica) is widely celebrated as one of the world's most breathtakingly beautiful and critically endangered arachnids, endemic to Andhra Pradesh.",distribution:"Restricted to a tiny, highly fragmented reserve forest area (<100 km²) located between Gooty and Nandyal in the Eastern Ghats of Andhra Pradesh.",habitat:"Strictly arboreal species inhabiting natural tree hollows, peeling bark, and crevices of mature deciduous forest trees.",morphology:"Displays brilliant, metallic electric-sapphire blue iridescence across its carapace and legs, adorned with intricate geometric white patches and bright yellow under-leg warning bands.",behaviour:"Fast-moving, nocturnal ambush predator. Constructs funnel-shaped silken webs inside tree cavities to detect vibration from approaching prey.",diet:"Consumes crickets, grasshoppers, moths, flying insects, and occasionally small geckos or tree frogs.",lifeCycle:"Females lay egg sacs containing 80 to 150 spiderlings inside tree cavities, guarding them fiercely until they disperse. Females live up to 15 years.",ecologicalImportance:"Top invertebrate predator regulating arboreal insect populations and maintaining ecological equilibrium in deciduous canopy systems.",conservation:"Critically Endangered on the IUCN Red List. Threatened by illegal poaching for the exotic pet trade, habitat clearance for agriculture, and firewood collection.",initiatives:"Protected under Andhra Pradesh Forest Department reserve forest monitoring and international CITES trade regulation."},INTERESTING_FACTS=[{title:"Structural Blue Coloration",description:"Its intense blue shimmer is produced by microscopic photonic crystal structures in leg scales reflecting blue wavelengths, rather than blue chemical pigments."},{title:"Discovered in Gooty Railway Yard",description:"First collected in 1899 by Reginald Innes Pocock from timber loads at the Gooty railway station in Andhra Pradesh."},{title:"Yellow Warning Bands",description:"Exhibits vivid canary-yellow underside leg bands used in threat displays to startle potential predators."},{title:"Extremely Restricted Global Range",description:"One of the rarest spiders on Earth, confined to a single contiguous tract of degraded forest in southern India."}],GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/Poecilotheria_metallica.jpg/800px-Poecilotheria_metallica.jpg",caption:"Gooty Sapphire Ornamental Tarantula (Poecilotheria metallica) displaying metallic blue iridescence",category:"Morphology"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Eastern_Ghats_Andhra_Pradesh_Forest.jpg/800px-Eastern_Ghats_Andhra_Pradesh_Forest.jpg",caption:"Eastern Ghats Reserve Forest — Native habitat in Andhra Pradesh",category:"Habitat"}],REFERENCES=[{text:"Pocock, R. I. (1899). The genus Poecilotheria: its habits and geographical distribution. Annals and Magazine of Natural History.",link:"#"},{text:"IUCN Red List of Threatened Species — Poecilotheria metallica assessment.",link:"https://www.iucnredlist.org"},{text:"Molur, S., et al. (2004). Status of South Asian Theraphosidae: Conservation Assessment and Management Plan.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={TARANTULA_INFO:TARANTULA_INFO,TAXONOMY_DATA:TAXONOMY_DATA,ECOLOGY_BEHAVIOUR:ECOLOGY_BEHAVIOUR,INTERESTING_FACTS:INTERESTING_FACTS,GALLERY_IMAGES:GALLERY_IMAGES,REFERENCES:REFERENCES});